public class EspressoMachineTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        EspressoMachine machine = new EspressoMachine(500, 100);
        check("new machine reports its beans", 100, machine.beanLevel());

        check("brew(2) brews 2", 2, machine.brew(2));
        check("water after 2 cups", 380, machine.waterLevel());
        check("beans after 2 cups", 84, machine.beanLevel());

        check("brew(10) is capped by the water", 6, machine.brew(10));
        machine.brew(1);
        check("a cup that cannot be paired takes no water", 20, machine.waterLevel());
        check("running total of cups", 8, machine.cupsBrewed());

        machine.restock(100, 0);
        machine.brew(5);
        check("status text after a restock", "water=0ml beans=20g cups=10", machine.status());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
