public class EspressoMachine {

    private static final int WATER_PER_CUP = 60;
    private static final int BEANS_PER_CUP = 8;

    private final WaterTank tank;
    private final BeanHopper hopper;
    private int cupsBrewed = 0;

    public EspressoMachine(int water, int beans) {
        this.tank = new WaterTank(water);
        this.hopper = new BeanHopper(beans);
    }

    public int brew(int cups) {
        int brewed = 0;
        while (brewed < cups
                && tank.level() >= WATER_PER_CUP
                && hopper.level() >= BEANS_PER_CUP) {
            tank.take(WATER_PER_CUP);
            hopper.take(BEANS_PER_CUP);
            brewed++;
            cupsBrewed++;
        }
        return brewed;
    }

    public int waterLevel() {
        return tank.level();
    }

    public int beanLevel() {
        return hopper.level();
    }

    public void restock(int water, int beans) {
        tank.fill(water);
        hopper.fill(beans);
    }

    public int cupsBrewed() {
        return cupsBrewed;
    }

    public String status() {
        return "water=" + waterLevel() + "ml beans=" + beanLevel() + "g cups=" + cupsBrewed;
    }
}
